// above (not hand-maintained) so DD214/NGB22 state-signal extraction
// elsewhere (musterCallProcessor.js) can validate against real data instead
// of a second, driftable list of US states/territories.
export const STATE_AWARD_CODES = new Set(
  STATE_AWARD_FILES.map((file) => file.stateCode),
);
export const STATE_NAME_TO_CODE = Object.fromEntries(
  STATE_AWARD_FILES.map((file) => [file.state.toUpperCase(), file.stateCode]),
);

// Helper function to get ribbon color by category
function getRibbonColorByCategory(category) {
  const categoryColors = {
    valor: "bg-gradient-to-r from-blue-600 via-white to-red-600",
    service: "bg-gradient-to-r from-green-600 via-yellow-400 to-green-600",
    campaign: "bg-gradient-to-r from-yellow-500 via-green-600 to-red-500",
    unit: "bg-gradient-to-r from-blue-500 via-red-500 to-blue-500",
    reserve: "bg-gradient-to-r from-yellow-400 via-blue-600 to-yellow-400",
    foreign: "bg-gradient-to-r from-red-600 via-white to-green-600",
    // Used by state/territory National Guard awards (category values
    // observed across all 54 stateAwards/*.json files: achievement, service,
    // unit, valor — the first 4 categories above already cover the other 3).
    achievement: "bg-gradient-to-r from-amber-500 via-yellow-200 to-amber-500",
  };
  return categoryColors[category] || "bg-gray-400";
}

