// ============================================================================
// ALIAS AUGMENTATIONS - abbreviations the scraped manifest doesn't list yet
// ============================================================================
// ribbon_manifest.json is regenerated by scripts/ribbon_scraper.py, so any
// alias edited directly in that file gets silently overwritten on the next
// scrape. Real DD214/NGB22 forms sometimes use abbreviations Wikipedia's
// award pages don't list (or list differently) — those extra aliases live
// here instead, keyed by manifest award id, and get merged in below.
const AWARD_ALIAS_AUGMENTATIONS = {
  // NGB/DD214 forms commonly abbreviate this "MFOM"; manifest only has "MFO".
  multinational_force_observers_medal: ["MFOM"],
  // This specific NGB22 form uses "NOPDR"; manifest only has "NCOPDR".
  nco_professional_development_ribbon: ["NOPDR"],
  // NGB22 forms commonly abbreviate these "GWOTS"/"GWOTE"; manifest only has
  // the longer "GWOTSM"/"GWOTEM" forms, which don't substring-match "GWOTS".
  global_war_on_terrorism_service_medal: ["GWOTS"],
  global_war_on_terrorism_expeditionary_medal: ["GWOTE"],
};

// Aliases the scraped manifest lists for one award but that are, in real
// DD214 usage, too ambiguous/generic to safely attribute to THAT award --
// removed here (keyed by manifest award id) rather than hand-edited in
// ribbon_manifest.json, which gets silently overwritten on the next scrape.
// The award's own full name (always tokenized, see _matchAward) and any
// remaining, unambiguous aliases still match normally.
const AWARD_ALIAS_REMOVALS = {
  // "NDSM" is the universal DD214/NGB22 abbreviation for the (near-
  // universal) National Defense Service Medal, not this senior valor award --
  // Navy DSM must require its full name or the unambiguous "NAVY DSM".
  navy_distinguished_service_medal: ["NDSM"],
  // A single common English word ("...ASSIGNED TO RECRUITING DUTY...")
  // fabricates this ribbon from unrelated remarks text; the full name and
  // "NRSR" abbreviation remain unambiguous.
  navy_recruiting_service_ribbon: ["RECRUITING"],
};

// ============================================================================
// STATE AWARDS - never part of the scraped federal-only manifest
// ============================================================================
// Sourced from src/data/stateAwards/{code}.json (54 files: 50 states + DC +
// PR + GU + VI), researched separately from the federal Wikipedia scrape.
// Each award already carries scope:"state"/stateCode/inStatePrecedence
// instead of the federal manifest's branch/precedence shape — parseDD214Text,
// sortRibbonsByPrecedence, and getAwardsForBranch below all branch on
// `award.scope === "state"` to handle the two shapes correctly.
const STATE_AWARD_ENTRIES = STATE_AWARD_FILES.flatMap((file) =>
  file.awards.map((award) => ({
    ...award,
    // The abbreviation is a real identifier from the sourced data (not
    // invented) -- folding it into aliases lets it participate in matching
    // the same way manifest aliases do. MIN_ALIAS_LENGTH below still filters
    // out 2-char abbreviations as OCR-noise-prone, same as federal awards.
    aliases: Array.from(
      new Set([
        ...(award.aliases || []),
        ...(award.abbreviation ? [award.abbreviation] : []),
      ]),
    ),
    assetFilename: null,
  })),
);

const _applyAliasAugmentation = (award) => {
  const removals = new Set(
    (AWARD_ALIAS_REMOVALS[award.id] || []).map((a) => a.toUpperCase()),
  );
  const baseAliases = award.aliases.filter(
    (alias) => !removals.has(alias.toUpperCase()),
  );
  return {
    ...award,
    aliases: [...baseAliases, ...(AWARD_ALIAS_AUGMENTATIONS[award.id] || [])],
  };
};

