// ============================================================================
// DD214 PARSING
// ============================================================================

// Every place `token` occurs in `text` as its own token rather than merely as
// a substring of a longer alphanumeric run. Plain `.includes()` alias matching
// false-positives badly on compact "//"-delimited abbreviation formats (e.g.
// NGB22 Block 15: "NDSM//ASR//AAM-2//..."), where short aliases like "SM"
// (Soldier's Medal) or "AM" (Air Medal) are substrings of unrelated
// neighboring tokens ("NDSM", "AAM-2") and would otherwise be reported as
// awards the veteran never received. Sentence-style Block 13 text (aliases
// already separated by spaces/punctuation) is unaffected by this check.
function _boundaryOccurrences(text, token) {
  const isAlnum = (ch) => /[A-Z0-9]/.test(ch);
  const occurrences = [];
  let idx = text.indexOf(token);
  while (idx !== -1) {
    const before = idx === 0 ? "" : text[idx - 1];
    const afterIdx = idx + token.length;
    const after = afterIdx >= text.length ? "" : text[afterIdx];
    if (!isAlnum(before) && !isAlnum(after)) {
      occurrences.push({ start: idx, end: afterIdx });
    }
    idx = text.indexOf(token, idx + 1);
  }
  return occurrences;
}

// Two-character aliases ("LM" Legion of Merit, "SM" Soldier's Medal, "PH",
// "SS", "BS", "AM", "NC") are not distinctive enough to match on even with the
// word-boundary check above: OCR of a degraded DD214 scan emits standalone
// two-letter noise tokens (a garbled "13. DECORATIONS ... BADGES" form label
// came out as "AWAR LM ST DAS"), which are legitimately boundary-delimited and
// would fabricate exactly the high-value valor awards a veteran never
// received. Every award carrying a two-char alias also carries its full name
// and/or a 3+ character abbreviation.
const MIN_ALIAS_LENGTH = 3;

// Find EVERY place a single award's name or any of its aliases matches in
// normalizedText, returning all matched spans. Every occurrence matters, not
// just the first: the same federal award name can appear both nested inside a
// longer state award name ("TEXAS MEDAL OF HONOR") and standalone elsewhere in
// the same document, and a first-occurrence-only model would suppress the
// award on the strength of the nested occurrence and silently drop a real
// award the veteran holds. `matchedAlias` keeps its original meaning -- the
// award's own name if that matched, else the first matching alias -- because
// extractContext/detectDevices/detectQuantity search on it. It is uppercased
// (unlike the manifest's own mixed case) so it stays indexOf-locatable in
// normalizedText -- the researched state-award aliases are natural/title case
// ("Texas Medal of Honor"), so comparing them raw would silently never match.
function _matchAward(normalizedText, award) {
  const tokens = [award.name.toUpperCase()];
  for (const alias of award.aliases) {
    const upperAlias = alias.toUpperCase();
    if (upperAlias.length >= MIN_ALIAS_LENGTH) {
      tokens.push(upperAlias);
    }
  }

  let matchedAlias = "";
  const spans = [];
  for (const token of tokens) {
    const occurrences = _boundaryOccurrences(normalizedText, token);
    if (occurrences.length === 0) continue;
    if (!matchedAlias) matchedAlias = token;
    spans.push(...occurrences);
  }
  if (!matchedAlias) return null;

  return { award, matchedAlias, spans };
}

// Scan EVERY award in MASTER_AWARDS (no branch/stateCode eligibility gate)
// for a name/alias match, purely to know what the raw text actually
// contains. Used only as the reference set for nested-match suppression
// below -- an award found here is never reported on its own unless it also
// passes the real branch/stateCode eligibility gate (see
// parseDD214Text/_suppressNestedAwardMatches).
function _matchAllAwardSpans(normalizedText) {
  const processedIds = new Set();
  const spans = [];

  for (const award of MASTER_AWARDS) {
    if (processedIds.has(award.id)) continue;
    const hit = _matchAward(normalizedText, award);
    if (hit) {
      processedIds.add(award.id);
      spans.push(hit);
    }
  }

  return spans;
}

function _isEligibleAward(award, branch, stateCode) {
  if (award.scope === "state") {
    // State-scoped awards carry no `branch` array at all (see the state
    // JSON schema) and are only eligible when the caller resolved a
    // matching stateCode -- without one, only federal awards can match.
    return Boolean(stateCode) && award.stateCode === stateCode;
  }
  return award.branch.includes(branch);
}

// Longest-match-wins: MASTER_AWARDS merges 780 state awards on top of the 89
// federal ones, and many state award full names/abbreviations legitimately
// CONTAIN a federal award's full name/abbreviation as a substring (e.g.
// Texas's "Texas Medal of Honor" alias contains the federal "Medal of
// Honor"; Hawaii's "HSM" abbreviation is verbatim identical to the federal
// Humanitarian Service Medal's). Returns the Set of `candidates` entries (by
// reference) that should NOT be reported.
function _suppressNestedAwardMatches(candidates, allSpans) {
  const suppressed = new Set();

  for (const a of candidates) {
    // An award is only suppressed when EVERY one of its occurrences is
    // accounted for by a more specific reading. A single unexplained
    // occurrence means the veteran really does hold the award -- a document
    // listing both "TEXAS MEDAL OF HONOR" and a standalone "MEDAL OF HONOR",
    // or both "DEFENSE MERITORIOUS SERVICE MEDAL" and "MERITORIOUS SERVICE
    // MEDAL" (DD214 precedence order lists them exactly that way), must
    // report both awards.
    const everyOccurrenceExplained = a.spans.every((span) => {
      const spanLen = span.end - span.start;

      // Rule 1 (unambiguous from the text alone): some award's name/alias --
      // reportable to this veteran or not -- strictly longer and fully
      // containing this occurrence exists in the raw text. The text itself
      // proves this occurrence is the wrong (nested, less specific) read
      // regardless of whether the more specific award actually belongs to
      // this veteran -- a Texas-shaped collision must not resolve to the
      // federal award for an Oregon veteran, or for no state at all, either.
      const hasLongerContainer = allSpans.some(
        (b) =>
          b.award.id !== a.award.id &&
          b.spans.some(
            (bSpan) =>
              bSpan.start <= span.start &&
              span.end <= bSpan.end &&
              bSpan.end - bSpan.start > spanLen,
          ),
      );
      if (hasLongerContainer) return true;

      // Rule 2 (ambiguous, needs the veteran's own scope to resolve): an
      // EXACT-span tie, e.g. the "HSM" abbreviation shared verbatim by the
      // federal Humanitarian Service Medal and Hawaii's own -- abbreviations
      // are meant to be unambiguous, unlike full names, which can legitimately
      // nest. Only resolved in favor of the state award when that state award
      // is itself reportable to this veteran (their own resolved stateCode);
      // a bare abbreviation must not be reinterpreted as a different state's
      // award for a veteran who never claimed that state.
      return candidates.some(
        (b) =>
          b !== a &&
          b.award.scope === "state" &&
          a.award.scope !== "state" &&
          b.spans.some(
            (bSpan) =>
              bSpan.start === span.start && bSpan.end - bSpan.start === spanLen,
          ),
      );
    });

    if (everyOccurrenceExplained) {
      suppressed.add(a);
    }
  }

  return suppressed;
}

/**
 * Parse DD214 text to extract awards with devices
 * @param {string} rawText - Raw text from DD214 Block 13/18
 * @param {string} branch - Veteran's primary branch of service
 * @param {string} [stateCode] - Veteran's National Guard state/territory code.
 *   State-scoped awards (scope:"state") only match when this is provided and
 *   equals the award's own stateCode; omitting it preserves the exact prior
 *   behavior of matching federal awards only.
 * @returns {Array} Array of { awardId, devices: [], quantity: number }
 */
export function parseDD214Text(rawText, branch = "Army", stateCode = null) {
  if (!rawText || typeof rawText !== "string") {
    return [];
  }

  // ============================================================
  // DD214 FORM STRUCTURE:
  // 1. FIELD LABELS = BOLD ALL CAPS
  // 2. INSTRUCTIONS = (parenthetic, often lowercase/mixed case)
  //    These contain EXAMPLE awards like "Silver Star, Bronze Star..."
  // 3. ACTUAL DATA = ALL CAPS, not in parentheses
  //
  // Key: Remove parenthetical content and lowercase text!
  // ============================================================

  let cleanedText = rawText;

  // STEP 1: Remove ALL parenthetical content (instructions/examples)
  // Excludes "/" from the character class: real DD214/NGB22 award data is
  // always "//"-delimited (the form's own field separator), and a genuine
  // single instructional parenthetical never contains a literal "//" inside
  // it. Some real NGB22 OCR scans have an unclosed opening paren right
  // before the actual award list (the form's own instructional text runs on
  // without its own closing paren) — without this exclusion, the greedy
  // match spans across the "//"-delimited award tokens to the NEXT ")" in a
  // later, unrelated field and deletes the entire real award list.
  // eslint-disable-next-line sonarjs/slow-regex -- {0,300} bounds backtracking to O(300n); measured 9.1s -> 55ms at 100k unmatched "(" (the "linear-time" claim this replaced was wrong -- unanchored /g matching retries the full backtrack at every start position when ")" never appears)
  cleanedText = cleanedText.replace(/\([^)/]{0,300}\)/g, " ");

  // STEP 2: Remove instructional patterns
  const INSTRUCTIONAL_PATTERNS = [
    /SILVER\s+STAR.*?BRONZE\s+STAR.*?AIR\s+MEDAL/gi,
    // \b-anchored so "E.G."/"I.E." only match as standalone abbreviations,
    // not as substrings inside real award names ("LEGION OF MERIT",
    // "SOLDIER'S MEDAL", "ARMY ACHIEVEMENT MEDAL" all contain "EG"/"IE").
    /SUCH\s+AS|FOR\s+EXAMPLE|\bE\.?G\.?\b|\bI\.?E\.?\b/gi,
    /EXAMPLES?\s+(?:OF\s+)?(?:DECORATIONS|MEDALS|AWARDS)/gi,
    // Remove words with 3+ lowercase letters (instructions, not data)
    /[a-z]{3,}/g,
  ];

  for (const pattern of INSTRUCTIONAL_PATTERNS) {
    cleanedText = cleanedText.replace(pattern, " ");
  }

  // If the cleaned text is nearly empty, the input was likely all instructional
  if (cleanedText.trim().length < 20) {
    return [];
  }

  // Normalize text: uppercase, remove extra spaces
  const normalizedText = cleanedText
    .toUpperCase()
    .replace(/\s+/g, " ")
    .replace(/[,;]/g, " ")
    .trim();

  const allSpans = _matchAllAwardSpans(normalizedText);
  const candidates = allSpans.filter((span) =>
    _isEligibleAward(span.award, branch, stateCode),
  );
  const suppressed = _suppressNestedAwardMatches(candidates, allSpans);

  const foundAwards = [];
  for (const candidate of candidates) {
    if (suppressed.has(candidate)) continue;
    const { award, matchedAlias } = candidate;

    // Detect devices
    const devices = detectDevices(normalizedText, matchedAlias, branch);

    // Detect quantity (for oak leaf clusters or stars)
    const quantity = detectQuantity(normalizedText, matchedAlias);

    foundAwards.push({
      awardId: award.id,
      award: award,
      devices: devices,
      quantity: quantity,
      matchedText: matchedAlias,
    });
  }

  return foundAwards;
}

/**
 * Detect devices attached to an award
 */
function _addOakLeafClusters(devices, context) {
  // eslint-disable-next-line sonarjs/slow-regex -- simple digit+alternation, no overlapping ambiguity; context is a short extracted snippet, not attacker-controlled
  const olcMatch = context.match(/(\d+)\s*(OLC|OAK\s*LEAF)/);
  if (olcMatch) {
    const count = parseInt(olcMatch[1], 10);
    const silverOLC = Math.floor(count / 5);
    const bronzeOLC = count % 5;

    for (let i = 0; i < silverOLC; i++) {
      devices.push({ type: "silver_olc", position: i });
    }
    for (let i = 0; i < bronzeOLC; i++) {
      devices.push({ type: "bronze_olc", position: silverOLC + i });
    }
  } else if (/OLC|OAK\s*LEAF/.test(context)) {
    devices.push({ type: "bronze_olc", position: 0 });
  }
}

function _addServiceStars(devices, context) {
  // eslint-disable-next-line sonarjs/slow-regex -- simple digit+alternation, no overlapping ambiguity; context is a short extracted snippet, not attacker-controlled
  const starMatch = context.match(/(\d+)\s*(STAR|STR|\*)/);
  if (!starMatch) return;

  const count = parseInt(starMatch[1], 10);
  const goldStars = Math.floor(count / 25);
  const silverStars = Math.floor((count % 25) / 5);
  const bronzeStars = count % 5;

  for (let i = 0; i < goldStars; i++) {
    devices.push({ type: "gold_star", position: i });
  }
  for (let i = 0; i < silverStars; i++) {
    devices.push({ type: "silver_star", position: goldStars + i });
  }
  for (let i = 0; i < bronzeStars; i++) {
    devices.push({
      type: "bronze_star",
      position: goldStars + silverStars + i,
    });
  }
}

function detectDevices(text, awardMatch, branch) {
  const devices = [];
  const context = extractContext(text, awardMatch, 50);

  // V Device (Valor)
  if (/W\/?V|WITH\s*V|V\s*DEVICE|VALOR/.test(context)) {
    devices.push({ type: "v_device", position: "center" });
  }

  // C Device (Combat)
  if (/W\/?C|WITH\s*C|C\s*DEVICE|COMBAT\s*DIST/.test(context)) {
    devices.push({ type: "c_device", position: "center" });
  }

  // R Device (Remote)
  if (/W\/?R|WITH\s*R|R\s*DEVICE|REMOTE/.test(context)) {
    devices.push({ type: "r_device", position: "center" });
  }

  // M Device (Mobilization - e.g. Armed Forces Reserve Medal, Oregon NG
  // Faithful Service Ribbon). NOTE: the Armed Forces Reserve Medal's
  // traditional device is an Hourglass per additional qualifying period, not
  // a numeral count — this detector only recognizes the literal "M device"
  // token, it does not attempt to translate a trailing numeral (e.g. the
  // "-2" in "AFRM-W/M-DEV-2") into hourglass count vs. award number; that
  // ambiguity is left undecided rather than guessed at.
  if (/W\/?M|WITH\s*M|M\s*DEVICE|MOBILIZATION/.test(context)) {
    devices.push({ type: "m_device", position: "center" });
  }

  // Oak Leaf Clusters (Army/Air Force)
  if (branch === "Army" || branch === "Air Force" || branch === "Space Force") {
    _addOakLeafClusters(devices, context);
  }

  // Service Stars (Navy/Marines/Coast Guard)
  if (branch === "Navy" || branch === "Marines" || branch === "Coast Guard") {
    _addServiceStars(devices, context);
  }

  // Arrowhead device
  if (/ARROWHEAD|ARROW/.test(context)) {
    devices.push({ type: "arrowhead", position: 0 });
  }

  return devices;
}

/**
 * Extract text context around a match
 */
function extractContext(text, match, chars) {
  const index = text.indexOf(match);
  if (index === -1) return text;

  let start = Math.max(0, index - chars);
  let end = Math.min(text.length, index + match.length + chars);

  // NGB22/DD214 "Block 15"-style forms pack awards as "//"-delimited tokens
  // (e.g. "AFRM-W/M-DEV-2//CAB//NATO-MDL") with far less than `chars`
  // between neighboring awards. A flat character radius bleeds a
  // neighboring award's own device/quantity markers into this award's
  // context. When "//" delimiters are present, clip the window to the
  // nearest one on each side so detection stays scoped to this award's own
  // token; sentence-style Block 13 text (no "//") is unaffected.
  const lastDelimBefore = text.slice(start, index).lastIndexOf("//");
  if (lastDelimBefore !== -1) {
    start = start + lastDelimBefore + 2;
  }
  const firstDelimAfter = text.slice(index + match.length, end).indexOf("//");
  if (firstDelimAfter !== -1) {
    end = index + match.length + firstDelimAfter;
  }

  return text.substring(start, end);
}

/**
 * Detect quantity of awards
 */
function detectQuantity(text, awardMatch) {
  const context = extractContext(text, awardMatch, 30);

  // Look for patterns like "(2)", "x2", "2nd", etc.
  // eslint-disable-next-line sonarjs/slow-regex -- simple single-quantifier patterns, no overlapping ambiguity
  const patterns = [/\((\d+)\)/, /x(\d+)/i, /(\d+)(?:ST|ND|RD|TH)\s*AWARD/i];

  for (const pattern of patterns) {
    const match = context.match(pattern);
    if (match) {
      return parseInt(match[1], 10);
    }
  }

  return 1;
}

// ============================================================================
// PRECEDENCE SORTING
// ============================================================================

// Per AR 670-1 (and equivalent branch regs), state awards sit below every
// federal award on a real uniform regardless of the state's own internal
// ordering. Used by both sortRibbonsByPrecedence and getAwardsForBranch so
// the two stay consistent.
function _precedenceSortValue(award, branch) {
  if (award?.scope === "state") {
    // 100000+ unambiguously sorts after any federal precedence value (the
    // highest observed federal Army precedence in the scraped manifest is
    // 75); null inStatePrecedence entries (no order asserted per-state) sort
    // last within their own state group via Number.POSITIVE_INFINITY.
    return 100000 + (award.inStatePrecedence ?? Number.POSITIVE_INFINITY);
  }
  return award?.precedence?.[branch] ?? 999;
}

/**
 * Sort ribbons by branch-specific order of precedence
 * @param {Array} awards - Array of award objects from parseDD214Text
 * @param {string} branch - Branch of service
 * @returns {Array} Sorted awards
 */
export function sortRibbonsByPrecedence(awards, branch) {
  if (!awards || !Array.isArray(awards)) {
    return [];
  }

  return [...awards].sort(
    (a, b) =>
      _precedenceSortValue(a.award, branch) -
      _precedenceSortValue(b.award, branch),
  );
}

/**
 * Get an award by ID
 */
export function getAwardById(awardId) {
  return MASTER_AWARDS.find((a) => a.id === awardId) || null;
}

// Awards persisted via addAward() (veteranProfile.js) only carry
// veteran-specific fields (name, dateReceived, notes, isCombat, ...) — never
// the visual metadata (assetFilename, ribbonColor, category) that lives on
// the matching MASTER_AWARDS entry, because that entry's own `id` is a
// stable slug (e.g. "national_defense_service_medal") while a stored
// award's `id` is a random `award_${Date.now()}_...` string with no
// relationship to it. Matching must happen by normalized name instead.
// Custom awards a veteran typed in manually (no MASTER_AWARDS match) fall
// back to the award as stored, so the caller's existing gray/color-class
// fallback still applies instead of crashing or showing a broken image.
export function enrichAwardForDisplay(award) {
  if (!award) return award;
  const normalizedName = (award.name || "").trim().toLowerCase();
  const masterMatch = MASTER_AWARDS.find(
    (a) => (a.name || "").trim().toLowerCase() === normalizedName,
  );
  if (!masterMatch) return award;
  return { ...masterMatch, ...award };
}

/**
 * Get awards applicable to a specific branch
 * @param {string} branch - Branch of service
 * @param {string} [stateCode] - Veteran's National Guard state/territory
 *   code. State-scoped awards only appear when this matches their stateCode.
 */
export function getAwardsForBranch(branch, stateCode = null) {
  return MASTER_AWARDS.filter((a) =>
    a.scope === "state"
      ? !!stateCode && a.stateCode === stateCode
      : a.branch.includes(branch),
  ).sort(
    (a, b) => _precedenceSortValue(a, branch) - _precedenceSortValue(b, branch),
  );
}

// ============================================================================
// RACK LAYOUT CALCULATIONS
// ============================================================================

/**
 * Calculate ribbon rack layout
 * @param {Array} sortedAwards - Awards sorted by precedence
 * @param {number} ribbonsPerRow - Ribbons per row (3 or 4)
 * @returns {Array} Array of rows, each containing ribbon objects
 */
export function calculateRackLayout(sortedAwards, ribbonsPerRow = 3) {
  if (!sortedAwards || sortedAwards.length === 0) {
    return [];
  }

  const rows = [];
  const totalRibbons = sortedAwards.length;

  // Calculate how many full rows and remainder
  const _fullRows = Math.floor(totalRibbons / ribbonsPerRow);
  const remainder = totalRibbons % ribbonsPerRow;

  let index = 0;

  // Top row (may be partial - should be centered)
  if (remainder > 0) {
    const topRow = {
      ribbons: sortedAwards.slice(index, index + remainder),
      isPartial: true,
      count: remainder,
      alignment: "center",
    };
    rows.push(topRow);
    index += remainder;
  }

  // Full rows
  while (index < totalRibbons) {
    const row = {
      ribbons: sortedAwards.slice(index, index + ribbonsPerRow),
      isPartial: false,
      count: ribbonsPerRow,
      alignment: "full",
    };
    rows.push(row);
    index += ribbonsPerRow;
  }

  return rows;
}

// ============================================================================
// UTILITY EXPORTS
// ============================================================================

export default {
  MASTER_AWARDS,
  DEVICES,
  PRECEDENCE_REGULATIONS,
  parseDD214Text,
  sortRibbonsByPrecedence,
  getAwardById,
  getAwardsForBranch,
  calculateRackLayout,
};
